package demo.payments;

import java.time.Instant;
import java.time.ZoneOffset;
import java.util.List;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class MerchantPaymentsQuery {

    private final JdbcClient jdbc;

    public MerchantPaymentsQuery(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public List<PaymentSummary> recent(long merchantId, Instant since, int limit) {
        return jdbc.sql("""
                SELECT id, reference, amount, currency, status, channel, created_at
                FROM payments
                WHERE merchant_id = :merchantId AND created_at >= :since
                ORDER BY created_at DESC
                LIMIT :limit""")
                .param("merchantId", merchantId)
                .param("since", since.atOffset(ZoneOffset.UTC))
                .param("limit", limit)
                .query(PaymentSummary.class)
                .list();
    }
}

