package demo.payments;

import java.math.BigDecimal;
import java.util.Optional;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class PaymentWriter {

    private final JdbcClient jdbc;

    public PaymentWriter(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public Optional<Long> authorise(long merchantId, String reference, BigDecimal amount, String currency, Channel channel) {
        return jdbc.sql("""
                INSERT INTO payments (merchant_id, reference, amount, currency, status, channel)
                VALUES (:merchantId, :reference, :amount, :currency, 'AUTHORISED', :channel)
                ON CONFLICT (merchant_id, reference) DO NOTHING
                RETURNING id""")
                .param("merchantId", merchantId)
                .param("reference", reference)
                .param("amount", amount)
                .param("currency", currency)
                .param("channel", channel.name())
                .query(Long.class)
                .optional();
    }
}

