package demo.costs;

import java.math.BigDecimal;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class BudgetLineRepository {

    private final JdbcClient jdbc;

    public BudgetLineRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public int add(long costCenterId, int fiscalYear, BigDecimal amount) {
        return jdbc.sql("""
                INSERT INTO budget_lines (cost_center_id, fiscal_year, amount)
                VALUES (:costCenterId, :fiscalYear, :amount)
                RETURNING id""")
                .param("costCenterId", costCenterId)
                .param("fiscalYear", fiscalYear)
                .param("amount", amount)
                .query(Integer.class)
                .single();
    }
}

